mapper.select:
SELECT T.ID, T.TXN_DATE, T.HANDLE_DATE_TIME, S.LINE_CODE, T.HANDLE_STATION_CODE, T.DEVICE_ID, T.CARD_TYPE, T.CARD_ID, T.TRX_TYPE, NVL(T.TRX_AMOUNT, 0) + NVL(T.OVERTIME_AMOUNT, 0) AS TRX_AMOUNT_TOTAL, T.RESERVE1, T.ITP_USER_ID FROM QRCODE_TXN_DETAIL T LEFT JOIN STATION_INFO S ON S.STATION_CODE = T.HANDLE_STATION_CODE WHERE T.TXN_DATE >= #{startDate,jdbcType=VARCHAR} AND T.TXN_DATE <= #{endDate,jdbcType=VARCHAR} AND T.HANDLE_DATE_TIME >= #{windowStart,jdbcType=VARCHAR} AND T.HANDLE_DATE_TIME < #{windowEnd,jdbcType=VARCHAR}
AND (T.HANDLE_DATE_TIME > #{lastHandleTime,jdbcType=VARCHAR} OR (T.HANDLE_DATE_TIME = #{lastHandleTime,jdbcType=VARCHAR} AND T.ID > #{lastId,jdbcType=NUMERIC}))
ORDER BY T.HANDLE_DATE_TIME, T.ID FETCH FIRST #{limit} ROWS ONLY
